struct Pending { Request req; ReplyPromise promise; Deadline when; };
void send(Socket& s, std::shared_ptr<Pending> p) {
  s.async_write_some(boost::asio::buffer(p->req),
      [p](const boost::system::error_code& ec, std::size_t n) { p->on_sent(ec, n); });
}
// p is the completion token: no request->handler lookup happens at completion time

awaitable<void> fetch(tcp::socket sock, Request req) {
  co_await async_write(sock, boost::asio::buffer(req), use_awaitable);
  std::array<char, 4096> buf;
  auto n = co_await sock.async_read_some(boost::asio::buffer(buf), use_awaitable);
  handle(req.id, std::string_view(buf.data(), n));
}

